INSERT INTO rag.documents (external_id, baslik, sirket, asset_id, tarih, tip, kategori, raw_text) VALUES
('DOC-001','THYAO 2026 2. Çeyrek Finansal Sonuçları','Türk Hava Yolları',1,'2026-07-28','bilanco',NULL,'Türk Hava Yolları 2026 yılı ikinci çeyreğinde net kârını bir önceki yılın aynı dönemine göre yüzde 18 artırdı. Yolcu doluluk oranı yüzde 84 seviyesinde gerçekleşti.

Şirketin dış hat yolcu sayısındaki artış, kargo gelirlerindeki yavaşlamayı dengeledi. Yönetim yıl sonu kapasite hedefini korudu.'),
('DOC-002','Havacılık Sektöründe Yakıt Maliyetleri Geriliyor',NULL,1,'2026-07-15','haber','piyasa','Jet yakıtı fiyatlarındaki gerileme havayolu şirketlerinin operasyonel maliyetlerini düşürüyor. Analistler bu eğilimin üçüncü çeyrekte kâr marjlarına olumlu yansıyacağını değerlendiriyor.'),
('DOC-003','SASA Polyester Kapasite Yatırımı Ertelendi','Sasa Polyester',4,'2026-06-30','duyuru',NULL,'Sasa Polyester, planlanan kapasite artırım yatırımını finansman koşulları nedeniyle bir yıl erteleme kararı aldı. Şirket açıklamasında mevcut üretim hattının verimliliğine odaklanılacağı belirtildi.

Karar sonrası hisse fiyatında baskı gözlendi. Şirketin borçluluk oranı sektör ortalamasının üzerinde seyrediyor.'),
('DOC-004','Petrokimya Sektörü Değerlendirme Raporu','Sasa Polyester',4,'2026-07-10','analist_raporu',NULL,'Petrokimya sektöründe talep zayıflığı sürüyor. Hammadde maliyetlerindeki oynaklık marjlar üzerinde baskı yaratmaya devam ediyor.

Sektörde yüksek borçluluğa sahip şirketler için finansman maliyeti kritik risk unsuru olmayı sürdürüyor. Kısa vadede toparlanma beklenmiyor.'),
('DOC-005','Gram Altın Talebinde Mevsimsel Artış',NULL,7,'2026-08-01','haber','altin','Gram altın talebinde mevsimsel artış gözleniyor. Kuyumculuk sektörü temsilcileri düğün sezonunun perakende talebi desteklediğini belirtiyor.'),
('DOC-006','Bitcoin Kurumsal Fon Girişleri Hızlandı',NULL,12,'2026-08-05','haber','kripto','Bitcoin''e yönelik kurumsal fon girişleri son çeyrekte hızlandı. Piyasa katılımcıları likidite koşullarındaki iyileşmenin fiyat üzerinde destekleyici olduğunu değerlendiriyor.

Yüksek oynaklık nedeniyle kripto varlıkların portföy içindeki ağırlığının risk toleransına göre sınırlandırılması öneriliyor.'),
('DOC-007','Nvidia Veri Merkezi Gelirleri Rekor Kırdı','Nvidia',17,'2026-07-22','bilanco',NULL,'Nvidia veri merkezi segmenti gelirleri çeyreklik bazda rekor seviyeye ulaştı. Yapay zeka altyapısına yönelik talep güçlü seyrini koruyor.

Şirket arz kısıtlarının kademeli olarak hafiflediğini bildirdi. Değerleme çarpanlarının tarihsel ortalamanın üzerinde olduğu vurgulanıyor.'),
('DOC-008','Küresel Faiz Beklentileri ve Portföy Dağılımı',NULL,NULL,'2026-08-08','analist_raporu',NULL,'Küresel faiz beklentilerindeki değişim varlık sınıfları arasındaki dağılımı yeniden şekillendiriyor. Tahvil getirilerindeki gerileme riskli varlıklara ilgiyi artırıyor.

Düşük risk toleransına sahip yatırımcılar için altın ve tahvil ağırlığının korunması, yüksek risk toleransına sahip yatırımcılar için hisse ve teknoloji ağırlığının değerlendirilmesi öneriliyor.');

